import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

mse_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mse_kernel(const float* pred, const float* target, float* global_sum, int num_elements) {
    extern __shared__ float shared[];
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    float val = 0.0f;

    if (idx < num_elements) {
        float diff = pred[idx] - target[idx];
        val = diff * diff;
    }
    shared[threadIdx.x] = val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            shared[threadIdx.x] += shared[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        atomicAdd(global_sum, shared[0]);
    }
}

torch::Tensor mse_cuda(torch::Tensor pred, torch::Tensor target) {
    TORCH_CHECK(pred.sizes() == target.sizes(), "Input tensors must have the same shape");
    int num_elements = pred.numel();
    auto sum_tensor = torch::zeros(1, torch::TensorOptions().dtype(torch::kFloat32).device(pred.device()));

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;
    size_t shared_mem_size = block_size * sizeof(float);

    mse_kernel<<<grid_size, block_size, shared_mem_size>>>(
        pred.data_ptr<float>(), target.data_ptr<float>(), sum_tensor.data_ptr<float>(), num_elements
    );

    cudaDeviceSynchronize();
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    float mean = sum_tensor.item<float>() / num_elements;
    return torch::tensor(mean, torch::TensorOptions().device(pred.device()));
}
"""

mse_cpp_source = "torch::Tensor mse_cuda(torch::Tensor pred, torch::Tensor target);"

mse_extension = load_inline(
    name="mse_extension",
    cpp_sources=mse_cpp_source,
    cuda_sources=mse_kernel_source,
    functions=["mse_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.mse_cuda = mse_extension.mse_cuda

    def forward(self, predictions, targets):
        return self.mse_cuda(predictions.contiguous(), targets.contiguous())
